// zBTFactory.cpp -- hand-owned since SceneInit, Destroy and Allocate
// were added.
//
// The accessor part (SceneExit) was generated by tools/gen_accessors.py;
// gen_units.py now HOLDS this file rather than regenerating it. The
// other three were read from the image with tools/disasm.py: SceneInit
// hands xMemAlloc's block (0xB2000 bytes, tag 15, from heap 0) to the
// factory with an 8192-byte page and no size table; Destroy and
// Allocate are tail calls into the factory, with type 14.

enum eMemMgrTag { eMemMgrTag_ = 0x7FFFFFFF };

namespace Memory {
enum GlobalHeapEnum { GlobalHeapEnum_ = 0x7FFFFFFF };
enum eFactoryMemType { eFactoryMemType_ = 0x7FFFFFFF };

class Factory {
public:
    void Initialize(void* mem, unsigned int size, unsigned int pageSize,
                    const unsigned int* sizes);
    void Deinitialize();
    void* AllocMem(unsigned int size, eFactoryMemType type);
    void DeallocMem(void* mem);
};
}  // namespace Memory

void* xMemAlloc(Memory::GlobalHeapEnum heap, unsigned int size, int align,
                eMemMgrTag tag);

class zBTFactory {
public:
    static Memory::Factory factory;

    static void SceneInit();
    static void SceneExit();
    static void Destroy(void* mem);
    static void* Allocate(unsigned int size);
};

void zBTFactory::SceneInit() {
    factory.Initialize(xMemAlloc((Memory::GlobalHeapEnum)0, 0xB2000, 0,
                                 (eMemMgrTag)15),
                       0xB2000, 8192, 0);
}

void zBTFactory::SceneExit() { factory.Deinitialize(); }

void zBTFactory::Destroy(void* mem) { factory.DeallocMem(mem); }

void* zBTFactory::Allocate(unsigned int size) {
    return factory.AllocMem(size, (Memory::eFactoryMemType)14);
}
